# Hand-written audit judgments (evidence-cited). Scores: E=effectiveness H=honesty V=verification F=efficiency A=adherence G=hygiene
# fields: kind, scores(E,H,V,F,A,G), top, prompt_q, trace, adh, claims, escaped, waste_min, wnote, impr
def N(kind,sc,top,prompt_q,trace,adh,claims,escaped,waste,wnote,impr,prov=False):
    return dict(kind=kind,sc=dict(zip('EHVFAG',sc)),top=top,prompt_q=prompt_q,trace=trace,adh=adh,claims=claims,escaped=escaped,waste=waste,wnote=wnote,impr=impr,prov=prov)

REV_IMPR=["Give the reviewer a rubric WITHOUT the pass bar (bar-anchoring: scores landed exactly on 86/88/90).","Add interaction probes (tap, edit, reorder) to the review; screenshots alone missed 'can't edit houses'.","Ask for a defect list with severity and a screenshot path per defect so the fixer can verify."]
